31	const itemSurcharge = (item: Item): number => {
32	  const base = BASE_PREMIUM[item.type] ?? 0;
33	  const totalRate = SURCHARGE_RATES
34	    .filter(({ applies }) => applies(item))
35	    .reduce((sum, { rate }) => sum + rate, 0);
36	  return base * totalRate;
