72	};
73	
74	const typeBasePremium = (type: string, count: number): number => {
75	  if (COMPONENT_TYPES.has(type) && count === COMPONENT_BLOCK_SIZE) {
76	    return COMPONENT_BLOCK_BASE;
77	  }
78	  return BASE_PREMIUM[type] * count;
79	};
